import{z as p,x as u,o as n,c as b,q as o,j as l,D as e,d as t,s as i,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Karatsuba","description":"","frontmatter":{"title":"Karatsuba","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karatsuba.md","filePath":"cs/karatsuba.md","lastUpdated":1791413859000}'),m={name:"cs/karatsuba.md"};function c(D,a,E,A,B,h){const s=u("Mermaid");return n(),b("div",null,[a[2]||(a[2]=o('<h1 id="karatsuba" tabindex="-1">Karatsuba <a class="header-anchor" href="#karatsuba" aria-label="Permalink to &quot;Karatsuba&quot;">​</a></h1><div class="epigraph"><p>把 $n$ 位数拆成两半，三次 $n/2$ 乘代替四次：$T(n)=3T(n/2)+O(n)$，即 $O(n^{\\log_2 3})$。</p><footer>—— 据 Karatsuba and Ofman, Multiplication of Multidigit Numbers on Automata, 1962；CLRS 第 4、30 章整理</footer></div><p>上一课<a href="/cs/bignum-arith">高精度算术</a>的小学乘法是 \\(O(n^2)\\)：拆成两半后，\\(xy\\) 看似需要四块交叉乘。缺口是 Karatsuba 的观察：用一次加减换掉一次乘。本课不重写进位规则；后课 FFT 把乘法次数再降，Toom–Cook 点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x=a B^{m}+b\\)，\\(y=c B^{m}+d\\)，\\(m=n/2\\)。小学：\\(ac,ad,bc,bd\\) 四次乘。Karatsuba：\\(p=ac\\)，\\(q=bd\\)，\\(r=(a+b)(c+d)\\)，则 \\(ad+bc=r-p-q\\)。三次递归乘 + \\(O(n)\\) 加减。主定理 \\(T(n)=3T(n/2)+O(n)=\\Theta(n^{\\log_2 3})\\approx n^{1.585}\\)。</p><p>缺口是这次代数恒等式，不是 FFT 的单位根。</p><h3 id="小-切回小学" tabindex="-1">小 \\(n\\) 切回小学 <a class="header-anchor" href="#小-切回小学" aria-label="Permalink to &quot;小 $n$ 切回小学&quot;">​</a></h3><p>递归到阈值以下要切回 \\(O(n^2)\\) 小学乘，常数项才好看——Karatsuba 的渐进优势要等 \\(n\\) 越过阈值，阈值随机器与实现而定，典型几十个机器字。不要对二十位的整数硬套三层递归。</p><p><span class="marginnote">数字实例：阈值取 32 个机器字时，一个 1024 字的数要递归五层（1024→512→256→128→64→32），乘法数 \\(3^5=243\\) 次、每次约 \\(32^2\\) 个字乘，合计约 24.9 万；小学乘法则要 \\(1024^2 \\approx 105\\) 万次——差四倍多。</span></p><p><span class="marginnote">Karatsuba 1962（与 Ofman）。Toom–Cook 把拆成 \\(k\\) 段、\\(2k-1\\) 次乘。后课 FFT/Schönhage–Strassen 近线性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现顺序：先把位数对齐成偶数、从中间切开；跑三次递归乘；合成时注意 \\(a+b\\)、\\(c+d\\) 可能比半长多一位，中间积多留一位；符号单独记录，核心只对绝对值相乘。</p>',12)),(n(),l(d,null,{default:e(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22x%2C%20y%20%E5%AF%B9%E5%8D%8A%22%5D%20--%3E%20P%5B%22ac%2C%20bd%2C%20(a%2Bb)(c%2Bd)%22%5D%0A%20%20P%20--%3E%20REC%5B%22%E4%B8%89%E6%AC%A1%E9%80%92%E5%BD%92%22%5D%0A%20%20REC%20--%3E%20COMB%5B%22%E7%A7%BB%E4%BD%8D%E7%9B%B8%E5%8A%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"三次递归乘彼此独立，可以并行；本课按串行计账。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,[t("机制就是那一条恒等式：交叉项 \\(ad+bc\\) 不必分开乘，\\(r-p-q\\) 一次合成，乘法数从四降到三，主定理随即把指数从 \\(2\\) 压到 \\(\\log_2 3\\)。它与"),r("a",{href:"/cs/divide-conquer"},"分治"),t("同形。正确性是多项式恒等——把 \\(x,y\\) 看成基 \\(B\\) 的多项式后逐点成立，与 \\(B\\) 取什么值无关。减法可能借位，高精度课已会处理。")],-1)),a[6]||(a[6]=r("p",null,[r("span",{class:"marginnote"},"直觉类比：\\((a+b)(c+d)\\) 是把四种配对「一锅端」全乘一遍；减掉两个纯项 \\(ac\\)、\\(bd\\)，锅里剩下的恰好是交叉项。本质是用加减法（便宜）换掉一次大乘法（贵）。")],-1)),(n(),l(d,null,{default:e(()=>[i(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22x%3D1234%2C%20y%3D5678%20%E6%8C%89%E5%9F%BA%20B%3D100%20%E5%88%87%E5%8D%8A%22%5D%20--%3E%20A1%5B%22a%3D12%2C%20b%3D34%2C%20c%3D56%2C%20d%3D78%22%5D%0A%20%20A1%20--%3E%20P%5B%22p%20%3D%2012%20%C3%97%2056%20%3D%20672%22%5D%0A%20%20A1%20--%3E%20Q%5B%22q%20%3D%2034%20%C3%97%2078%20%3D%202652%22%5D%0A%20%20A1%20--%3E%20R%5B%22r%20%3D%2046%20%C3%97%20134%20%3D%206164%22%5D%0A%20%20P%20--%3E%20C%5B%22%E4%BA%A4%E5%8F%89%E9%A1%B9%20%3D%20r%20%E2%88%92%20p%20%E2%88%92%20q%20%3D%202840%22%5D%0A%20%20Q%20--%3E%20C%0A%20%20R%20--%3E%20C%0A%20%20C%20--%3E%20F%5B%22%E5%90%88%E6%88%90%EF%BC%9A672%C3%9710000%20%2B%202840%C3%97100%20%2B%202652%20%3D%207006652%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>Strassen 的矩阵乘是同一思想的另一恒等式（七乘代八乘），后课展开，不要与本课混。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FFT 乘法。负数与模乘都可先乘再处理。后课默认：大整数库至少要有 Karatsuba 加阈值切换。下一课 FFT。</p><p><span class="marginnote">常见误区：以为渐进更优就能到处用。实际上 \\(n\\) 低于阈值时，递归与加减的开销反而拖慢速度——GMP 这类库都是混合策略：小数用小学乘，中数用 Karatsuba，更大才上 Toom–Cook 与 FFT。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三次半长乘代替四次，\\(O(n^{1.585})\\)。</li><li>小规模切回小学。</li><li>代数恒等式，不是近似。</li><li>出处：Karatsuba and Ofman, 1962。</li></ul>',6))])}const f=p(m,[["render",c]]);export{T as __pageData,f as default};
